import{_ as i,o as l,c as a,ae as t}from"./chunks/framework.jfJLTIcL.js";const b=JSON.parse('{"title":"下一版架构边界","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/architecture-next.md","filePath":"zh-CN/architecture-next.md","lastUpdated":1778672497000}'),p={name:"zh-CN/architecture-next.md"};function n(r,e,s,o,d,c){return l(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="下一版架构边界" tabindex="-1">下一版架构边界 <a class="header-anchor" href="#下一版架构边界" aria-label="Permalink to &quot;下一版架构边界&quot;">​</a></h1><p>本文记录下一版 VILab 架构的目标边界，用于指导后续服务端、Web 管理端、桌面端和 SDK 的改造。它描述的是目标方向，不等同于当前已经完全落地的实现。</p><p>下一阶段先收敛到一个核心能力：<strong>语音输入到文本输出</strong>。语音服务能力负责 ASR 和 LLM 处理，客户端只负责采集音频、展示结果或把结果插入到本机输入位置。</p><h2 id="核心结论" tabindex="-1">核心结论 <a class="header-anchor" href="#核心结论" aria-label="Permalink to &quot;核心结论&quot;">​</a></h2><ul><li>语音服务能力有两种承载形态：独立 VILab Server，以及桌面端内嵌本地服务。</li><li>Web 管理端是独立 VILab Server 的配置入口，只给管理员使用。</li><li>桌面端可以完全使用自己的内嵌本地服务，不依赖独立 VILab Server。</li><li>桌面端负责录音、快捷键、文本插入，并调用本地或远程语音服务。</li><li>SDK 只作为 WebSocket 流式语音客户端。</li><li>本阶段不做 pipeline 暴露。</li><li>本阶段不做用户级模型隔离。</li><li>本阶段不提供 HTTP 非流式转写能力。</li></ul><h2 id="服务能力形态" tabindex="-1">服务能力形态 <a class="header-anchor" href="#服务能力形态" aria-label="Permalink to &quot;服务能力形态&quot;">​</a></h2><p>下一版架构不是只有一个远程服务端。VILab 的语音能力可以由两种形态承载：</p><table tabindex="0"><thead><tr><th>形态</th><th>运行位置</th><th>典型使用方式</th><th>配置入口</th></tr></thead><tbody><tr><td>独立 VILab Server</td><td>服务器、Docker、云主机、局域网主机</td><td>多客户端共享、Web 管理、SDK 接入</td><td>Web 管理端</td></tr><tr><td>桌面端内嵌本地服务</td><td>用户自己的 Windows 或 macOS 设备</td><td>单机使用、离线或本机模型、本地文本插入</td><td>桌面端本地设置</td></tr></tbody></table><p>独立 VILab Server 和桌面端内嵌本地服务都可以提供“语音输入到文本输出”的能力。区别在于：独立服务端面向多客户端共享和集中配置；桌面端内嵌本地服务面向单机体验，可以完全不连接独立 VILab Server。</p><h2 id="独立服务端职责" tabindex="-1">独立服务端职责 <a class="header-anchor" href="#独立服务端职责" aria-label="Permalink to &quot;独立服务端职责&quot;">​</a></h2><p>独立 VILab Server 只对外提供语音输入到文本输出相关能力。</p><p>独立服务端负责：</p><ul><li>接收实时音频输入。</li><li>调用当前全局 ASR 配置，返回 ASR 中间结果和最终结果。</li><li>调用当前全局 LLM 配置，返回 LLM 流式结果和最终结果。</li><li>聚合一次语音会话的最终输出。</li><li>保存和读取全局 ASR、LLM、Prompt 等服务配置。</li><li>提供 Web 管理端需要的管理接口。</li><li>提供 WebSocket 实时语音协议。</li></ul><p>独立服务端不负责：</p><ul><li>桌面窗口、托盘、系统快捷键。</li><li>本机麦克风选择。</li><li>文本插入、剪贴板、输入法桥接。</li><li>每个普通用户自己的模型偏好。</li><li>SDK 本地模型配置。</li><li>客户端侧 UI 交互状态。</li></ul><p>当前阶段的独立服务端配置是全局配置。管理员在 Web 管理端切换 ASR 或 LLM 后，所有连接到该独立服务端的桌面端、Web 使用端和 SDK 调用方都会使用新的全局配置。</p><h2 id="web-管理端职责" tabindex="-1">Web 管理端职责 <a class="header-anchor" href="#web-管理端职责" aria-label="Permalink to &quot;Web 管理端职责&quot;">​</a></h2><p>Web 管理端只给管理员使用，普通内测用户不会拿到管理地址。它管理的是独立 VILab Server 的全局配置，不管理用户本机桌面端的内嵌本地服务。</p><p>Web 管理端负责：</p><ul><li>配置全局 ASR Provider、URL、Key 和模型名。</li><li>配置全局 LLM Provider、URL、Key 和模型名。</li><li>配置全局 Prompt 或文本后处理策略。</li><li>测试 ASR、LLM 和完整语音链路。</li><li>查看服务端运行状态。</li></ul><p>Web 管理端不面向普通用户提供模型切换能力。普通用户只使用语音能力，不修改服务端配置。</p><p>权限模型在当前内测阶段保持简单。可以先使用固定管理员入口、固定账号密码、固定 token，或者仅在受控内网环境暴露管理端。完整账号体系、数据库用户表、细粒度权限和多租户隔离不属于本阶段目标。</p><h2 id="桌面端职责" tabindex="-1">桌面端职责 <a class="header-anchor" href="#桌面端职责" aria-label="Permalink to &quot;桌面端职责&quot;">​</a></h2><p>桌面端是本机用户体验入口，同时保留自己的内嵌本地服务。桌面端可以完全使用本地服务完成 ASR、LLM 和文本插入，也可以连接独立 VILab Server 使用远程语音服务。</p><p>桌面端负责：</p><ul><li>录音。</li><li>全局快捷键。</li><li>显示录音和转写状态。</li><li>调用本机内嵌服务或独立 VILab Server 的 WebSocket 实时语音接口。</li><li>接收 ASR 和 LLM 的流式事件。</li><li>把最终文本插入到当前应用的光标位置。</li><li>在插入失败时提供复制、重试或错误提示。</li></ul><p>文本插入是桌面端特有能力。服务端只返回文本，不操作用户本机。桌面端收到最终文本后，可以通过粘贴、模拟输入或输入法桥接把文本写入微信、飞书、浏览器、VS Code 等当前前台应用。</p><h3 id="输入法端边界" tabindex="-1">输入法端边界 <a class="header-anchor" href="#输入法端边界" aria-label="Permalink to &quot;输入法端边界&quot;">​</a></h3><p>输入法端是桌面端的本机 OS 输入前端。Windows 输入法和 macOS 输入法继续保留当前设计：输入法进程读取桌面客户端生成的 <code>ime-bridge.json</code>，调用桌面客户端内嵌本地服务的 <code>/admin/ime/*</code> 接口，由桌面客户端完成录音、ASR 和 LLM 后处理，再由输入法端把最终文本写回当前输入框。</p><p>当前阶段输入法端不直接连接独立 VILab Server，也不管理 ASR、LLM、Provider Key 或服务端模型。后续如果需要接入独立服务端能力，也应优先保持“输入法端 -&gt; 桌面客户端本地服务 -&gt; 独立 VILab Server”的桥接路径，让输入法端继续只负责本机输入和文本写回。</p><p>桌面端连接独立 VILab Server 时，不负责：</p><ul><li>管理 ASR Provider。</li><li>管理 LLM Provider。</li><li>保存 Provider API Key。</li><li>选择服务端模型。</li><li>修改独立服务端全局配置。</li><li>直接连接 LLM 做后处理。</li></ul><p>桌面端使用内嵌本地服务时，可以继续保留当前桌面端已有的本地配置能力。这是桌面端单机路径，不等同于修改独立 VILab Server，也不会影响其他用户。</p><h2 id="sdk-职责" tabindex="-1">SDK 职责 <a class="header-anchor" href="#sdk-职责" aria-label="Permalink to &quot;SDK 职责&quot;">​</a></h2><p>SDK 是 VILab 语音服务的实时客户端。它可以连接独立 VILab Server，也可以连接桌面端暴露的本机服务地址。</p><p>SDK 保留：</p><ul><li>连接 VILab 语音服务地址。</li><li>建立 WebSocket 实时语音会话。</li><li>发送音频流。</li><li>接收 ASR 中间结果。</li><li>接收 ASR 最终结果。</li><li>接收 LLM 流式结果。</li><li>接收 LLM 最终结果。</li><li>接收 session 完成事件和错误事件。</li></ul><p>SDK 移除或不再扩展：</p><ul><li>HTTP 非流式转写。</li><li>pipeline 选择。</li><li>SDK-local LLM config。</li><li><code>models.add/update/delete/use</code> 这类本地模型管理。</li><li><code>mode.set(local/remote)</code> 这类客户端模式切换。</li><li>SDK 直连 LLM。</li><li>Provider Key 管理。</li><li>Admin API 调用。</li></ul><p>新 SDK 的职责不是“管理 VILab”，而是“消费 VILab 语音服务的实时语音能力”。</p><h2 id="本阶段不做-pipeline" tabindex="-1">本阶段不做 pipeline <a class="header-anchor" href="#本阶段不做-pipeline" aria-label="Permalink to &quot;本阶段不做 pipeline&quot;">​</a></h2><p>下一阶段不向客户端暴露 <code>raw</code>、<code>smart_clean</code>、<code>polish</code> 等 pipeline。</p><p>服务端内部可以仍然有处理阶段，但客户端不选择 pipeline。一次语音会话默认执行固定链路：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>音频输入</span></span>
<span class="line"><span>  -&gt; ASR 中间结果</span></span>
<span class="line"><span>  -&gt; ASR 最终结果</span></span>
<span class="line"><span>  -&gt; LLM 流式结果</span></span>
<span class="line"><span>  -&gt; LLM 最终结果</span></span>
<span class="line"><span>  -&gt; 会话最终文本</span></span></code></pre></div><p>如果后续需要支持“只 ASR 不润色”或“不同处理策略”，应先重新讨论协议，不在本阶段提前设计复杂 pipeline。</p><h2 id="本阶段不做用户隔离" tabindex="-1">本阶段不做用户隔离 <a class="header-anchor" href="#本阶段不做用户隔离" aria-label="Permalink to &quot;本阶段不做用户隔离&quot;">​</a></h2><p>当前内测阶段不做 per-user routing，也不做 per-key 模型隔离。</p><p>这意味着：</p><ul><li>独立服务端只有一套全局 ASR 配置。</li><li>独立服务端只有一套全局 LLM 配置。</li><li>管理员切换独立服务端模型会影响所有连接到该服务端的调用方。</li><li>普通用户不能修改模型。</li><li>SDK 不能为某个用户单独切换独立服务端模型。</li></ul><p>桌面端内嵌本地服务的配置只作用于本机桌面端，不属于独立服务端的用户隔离问题。</p><p>如果未来要支持多用户、多租户或不同项目使用不同模型，需要新增独立的用户、项目、权限和 routing 设计。当前文档不提前承诺这部分能力。</p><h2 id="实时语音链路" tabindex="-1">实时语音链路 <a class="header-anchor" href="#实时语音链路" aria-label="Permalink to &quot;实时语音链路&quot;">​</a></h2><p>目标链路如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Desktop / Web 使用端 / SDK</span></span>
<span class="line"><span>  -&gt; WebSocket</span></span>
<span class="line"><span>  -&gt; 独立 VILab Server 或桌面端内嵌本地服务</span></span>
<span class="line"><span>  -&gt; ASR Provider 或服务端本地 ASR Worker</span></span>
<span class="line"><span>  -&gt; LLM Provider</span></span>
<span class="line"><span>  -&gt; WebSocket events</span></span>
<span class="line"><span>  -&gt; Client 展示或插入最终文本</span></span></code></pre></div><p>服务端事件至少需要表达：</p><ul><li>会话已开始。</li><li>ASR 中间结果。</li><li>ASR 最终结果。</li><li>LLM 流式增量。</li><li>LLM 最终结果。</li><li>会话完成。</li><li>错误。</li><li>取消。</li></ul><p>具体事件名、消息字段、音频格式、二进制帧规则和关闭语义由 WebSocket 协议文档单独定义。</p><h2 id="文档拆分" tabindex="-1">文档拆分 <a class="header-anchor" href="#文档拆分" aria-label="Permalink to &quot;文档拆分&quot;">​</a></h2><p>本文件只定义架构边界。后续还需要继续确定：</p><ul><li><a href="/docs/zh-CN/realtime-websocket-api">WebSocket 实时语音协议</a>：WebSocket 实时语音协议。</li><li><a href="/docs/zh-CN/sdk-next">下一版 SDK 设计</a>：SDK 新 API、事件类型和迁移策略。</li></ul><p>实现改造应先对齐这三份文档，再拆分 PR 落地。</p>`,61)])])}const S=i(p,[["render",n]]);export{b as __pageData,S as default};
